import React, {useState} from 'react'
import {useDispatch, useSelector} from "react-redux"
import {FloatButton, Select} from "antd"
import {SyncOutlined} from "@ant-design/icons"

import {bookActions, selectRepeatState} from "../../state/book-reducer"

export function FloatingMenu({count}) {
  const [expand, setExpand] = useState(false)
  const repeat = useSelector(selectRepeatState)
  const dispatch = useDispatch()
  const inFlowFloatStyle = {position: "static", insetInlineEnd: "auto", bottom: "auto"}

  const getArray = length => {
    return Array(length).fill(1).map((item, index) => ({value: index + 1, label: index + 1}))
  }

  let repeatString = (() => {
    let repeatString = null
    if (repeat.oneToggle) {
      repeatString = 1
    } else if (repeat.manyToggle) {
      repeatString = repeat.manyToggle ? `${repeat.fromSloka} - ${repeat.toSloka}` : ""
    }
    return !expand ? repeatString : ""
  })()
  return <>
    {expand &&
      <div className={"fixed bottom-[4rem] right-[max(1.5rem,calc((100vw-56rem)/2+1.5rem))] z-[1000] flex flex-col items-end gap-[1rem]"}>
        {/* ONE */}
        <FloatButton type={repeat.oneToggle ? "primary" : ""}
                     description={"1"}
                     className={"bg-amber-300"}
                     style={inFlowFloatStyle}
                     onClick={() => dispatch(bookActions.one())}/>
        <div className={"flex items-center gap-[0.5rem]"}>
          <FloatButton
            shape={"square"}
            description={<Select className={"w-[4rem]"} defaultValue={repeat.fromSloka}
                                 options={getArray(count)}
                                 onSelect={val => dispatch(bookActions.repeatFrom(val))}/>}
            className={"w-[4rem] bg-amber-300"}
            style={inFlowFloatStyle}/>
          <FloatButton
            shape={"square"}
            description={<Select className={"w-[4rem]"} defaultValue={repeat.toSloka} options={getArray(count)}
                                 onSelect={val => dispatch(bookActions.repeatTo(val))}/>}
            className={"w-[4rem] bg-amber-300"}
            style={inFlowFloatStyle}/>
          {/* A-B */}
          <FloatButton type={repeat.manyToggle ? "primary" : ""}
                       description={"A-B"}
                       className={"bg-amber-300"}
                       style={inFlowFloatStyle}
                       onClick={() => dispatch(bookActions.many())}/>
        </div>
      </div>
    }
    <FloatButton shape={"square"}
                 icon={<SyncOutlined/>}
                 description={repeatString}
                 type={repeatString ? "primary" : ""}
                 className={"bottom-[1rem] right-[max(1.5rem,calc((100vw-56rem)/2+1.5rem))] w-[4rem] h-[2rem] bg-amber-300"}
                 onClick={() => setExpand(!expand)}/>
  </>
}
