import {Button, Card} from "antd";
import {useState} from "react";
import {useSwipeable} from "react-swipeable";

export default function VsnSloka({sloka, num, slokaMeaning}) {
  const [collapseNum, setCollapseNum] = useState(null);

  const [currNamamIndex, setCurrNamamIndex] = useState(null);
  const handlers = useSwipeable({
    onSwipedLeft: () => setCurrNamamIndex(i => isValid(i + 1) ? i + 1 : i),
    onSwipedRight: () => setCurrNamamIndex(i => isValid(i - 1) ? i - 1 : i),
  });

  const isValid = namamIndex => {
    return !!slokaMeaning?.["namam-meanings"]?.find(namamObj => (namamObj.number === namamIndex));
  }

  const toggleSlokaMeaning = e => slokaNumber => {
    e.stopPropagation()
    setCollapseNum(slokaNumber === collapseNum ? 0 : slokaNumber)
  }

  /*--------- 1. Slokam ---------*/
  const renderSloka = () => {
    return <div className="sloka-lines">
      {/* Button */}
      <Button className="sloka-meaning-button"
              style={{border: collapseNum === num ? "2px solid #906720" : 0}}
              onClick={e => toggleSlokaMeaning(e)(num)}>
        {num}
      </Button>
      {/* Slokam */}
      <div dangerouslySetInnerHTML={{__html: sloka}}>
      </div>
    </div>
  }

  /*--------- 2. comma separated Slokam ---------*/
  const renderSlokaNamalu = () => {
    return <div className="sloka-meaning pb-3">
      {
        slokaMeaning?.["namam-meanings"]?.map((namamObj, index, arr) => {
          const highlight = currNamamIndex === namamObj.number ? "underline" : "";
          return (
            <span key={index} onClick={() => setCurrNamamIndex(namamObj.number)}>
              <span className={highlight}>{namamObj.namam || <br/>}</span>
              {index < arr.length - 1 && namamObj.namam ? ", " : ""}
            </span>
          )
        })
      }
    </div>
  }

  /*--------- 3. one Namam Meaning ---------*/
  const renderNamamMeaning = () => {
    if (!currNamamIndex) {
      return;
    }

    let namamObj = slokaMeaning?.["namam-meanings"]?.find(namamObj => (namamObj.number === currNamamIndex))
    let oneNamamMeaning = {
      __html: namamObj?.number + ": " + namamObj?.namam + " 🌼🌼 " + (namamObj?.meaning || "")
    }
    return (
      <div {...handlers} className="sloka-translation"
           dangerouslySetInnerHTML={oneNamamMeaning}
      >
      </div>
    )
  }

  const handleKeyDown = (event) => {
    switch (event.key) {
      case 'ArrowDown':
        break;
      case 'ArrowUp':
        break;
      case 'ArrowLeft':
        setCurrNamamIndex(i => isValid(i - 1) ? i - 1 : i)
        break;
      case 'ArrowRight':
        setCurrNamamIndex(i => isValid(i + 1) ? i + 1 : i)
        break;
    }
  }

  return sloka && (
    <Card
      size="small"
      className="sloka-card text-left"
      bodyStyle={{padding: 0}}
      tabIndex={0}
      onKeyDown={handleKeyDown}
    >
      {renderSloka()}
      <div style={{display: collapseNum === num ? "flex" : "none", padding: "0.6rem"}}>
        <div style={{flexGrow: 1, width: 0}}>
          {renderSlokaNamalu()}
          {renderNamamMeaning()}
        </div>
      </div>
    </Card>
  )
}
